import sys

n = int(input())
t = int(input())

switches = {}
for _ in range(n):
    sid, state, left, right = input().split()
    switches[sid] = {"state": state, "L": left, "R": right}

for _ in range(t):
    curr = "1"
    while curr in switches:
        s = switches[curr]
        next_node = s[s["state"]]
        s["state"] = "R" if s["state"] == "L" else "L"
        curr = next_node
    print(curr)

